edits.replace:
let escaped = query.replace('\\', "\\\\").replace('%', "\\%").replace('_', "\\_");
let pattern = format!("%{escaped}%");
let rows = tracker
    .run(
        sqlx::query(
            "SELECT id, name, price_cents FROM products WHERE name ILIKE $1 ORDER BY id LIMIT 20",
        )
        .bind(pattern)
        .fetch_all(pool),
    )
    .await?;
